import{_ as a,o as r,c as t,a2 as e}from"./chunks/framework.A5mep7Fe.js";const _=JSON.parse('{"title":"🌍 03 · 世界模型（World Model）","description":"","frontmatter":{},"headers":[],"relativePath":"05-算法岗-前沿与具身/03-世界模型.md","filePath":"05-算法岗-前沿与具身/03-世界模型.md","lastUpdated":1786806808000}'),l={name:"05-算法岗-前沿与具身/03-世界模型.md"};function i(n,o,s,d,h,u){return r(),t("div",null,[...o[0]||(o[0]=[e('<h1 id="🌍-03-·-世界模型-world-model" tabindex="-1">🌍 03 · 世界模型（World Model） <a class="header-anchor" href="#🌍-03-·-世界模型-world-model" aria-label="Permalink to &quot;🌍 03 · 世界模型（World Model）&quot;">​</a></h1><blockquote><p>让 AI「在脑中预演未来」——学习环境的内部模型，用于预测、规划与控制。AGI 路线的重要候选。</p></blockquote><hr><h2 id="一、核心思想" tabindex="-1">一、核心思想 <a class="header-anchor" href="#一、核心思想" aria-label="Permalink to &quot;一、核心思想&quot;">​</a></h2><p>人类下棋/行动前会在脑中模拟后果。世界模型 = 让 AI 学习一个<strong>对环境的压缩、可预测的表征</strong>，能在内部「想象」未来状态。</p><h2 id="二、代表方法" tabindex="-1">二、代表方法 <a class="header-anchor" href="#二、代表方法" aria-label="Permalink to &quot;二、代表方法&quot;">​</a></h2><ul><li><strong>JEPA（Joint Embedding Predictive Architecture，LeCun 提出）</strong>：在<strong>表征空间</strong>预测，而非像素空间，避免生成冗余细节。</li><li><strong>Dreamer / DreamerV3</strong>：在学到的世界模型里用 RL 规划，样本效率高（机器人/游戏）。</li><li><strong>Diffusion-based 世界模型</strong>：用扩散生成未来帧（视频模型天然是世界模型雏形）。</li><li><strong>Simulator 路线</strong>：用真实数据训一个可微 simulator。</li></ul><h2 id="三、为什么重要" tabindex="-1">三、为什么重要？ <a class="header-anchor" href="#三、为什么重要" aria-label="Permalink to &quot;三、为什么重要？&quot;">​</a></h2><ul><li><strong>规划</strong>：在模型内 rollout 多条未来，选最优行动（比无模型 RL 高效）</li><li><strong>数据效率</strong>：减少对真实交互的依赖</li><li><strong>AGI</strong>：被认为是通向「自主智能体」的关键组件</li></ul><h2 id="四、争议与未定论" tabindex="-1">四、争议与未定论 <a class="header-anchor" href="#四、争议与未定论" aria-label="Permalink to &quot;四、争议与未定论&quot;">​</a></h2><ul><li>像素级世界模型冗余且易失真；表征级（JEPA）更优雅但难训练</li><li>与「视频生成模型是否等于世界模型」仍有学术争论</li><li>当前多在游戏/仿真验证，真实复杂世界仍远</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：世界模型和视频生成模型有什么区别？</strong></p><blockquote><p>视频生成目标是「看起来真」，未必遵循物理因果；世界模型目标是「可预测、可控、支撑规划」，强调因果与状态转移。两者有交集但目的不同。</p></blockquote><p><strong>Q2：JEPA 为什么在表征空间预测？</strong></p><blockquote><p>像素级预测被迫重建无关细节（如一片叶子的纹理），浪费容量且易失真；表征空间只预测语义上有意义的高层变化，更高效、更鲁棒。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-AGI与前沿思考">04-AGI 与前沿思考</a></p>',18)])])}const p=a(l,[["render",i]]);export{_ as __pageData,p as default};
